/* ===== fp-ui.js ===== */
/* Find Prop — shared UI components. Each is defined once here and used by every screen through a custom tag,
   e.g. <fp-header role="user" active="buy">, so the header, footer, cards and ad container cannot drift between screens.
   Also: #state handling (data-show / data-default), tiny click behaviours for the mockups. */
window.FP = window.FP || {};
(function () {
  const icon = FP.icon;
  const D = FP.data;
  const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
  const asBool = (v) => v === '' || v === true || v === 'true';
  const list = (v) => (v == null || v === '' ? [] : String(v).split(',').map((s) => s.trim()));
  const T = (FP.tags = {});

  /* ── Navigation ───────────────────────────────── */
  const NAV = [['buy', 'Buy', 'search.html#buy'], ['rent', 'Rent', 'search.html#rent'], ['projects', 'Projects', 'projects.html'], ['ai', 'AI Search', 'ai-search.html'], ['contact', 'Contact', 'contact.html']];

  FP.accountMenu = function (role) {
    const u = D.user;
    const chip = { builder: '<span class="role-chip">Builder</span>', admin: '<span class="role-chip admin">Super admin</span>', agent: '<span class="role-chip">Agent</span>' }[role] || '';
    const row = (ic, label, href, meta, metaCls = 'n') => `<a href="${href}" role="menuitem">${icon(ic)}${label}${meta ? `<span class="meta ${metaCls}">${meta}</span>` : ''}</a>`;
    const portals = {
      builder: row('briefcase', 'Builder portal', 'builder-dashboard.html'),
      admin: row('layers', 'Admin portal', 'admin-overview.html'),
      agent: `<a href="dashboard.html" role="menuitem">${icon('users')}Agent workspace<span class="flag" style="margin-left:auto">Proposed</span></a>`,
    }[role] || '';
    return `<div class="menu hdr-menu" role="menu" aria-label="Account">
      <div class="who"><span class="avatar lg">${u.initials}</span><div><b>${u.name}</b><span>${u.email}</span>${chip ? `<div>${chip}</div>` : ''}</div></div>
      <div class="sep"></div>
      <div class="lbl overline">Dashboard</div>
      ${row('heart', 'Saved homes', 'dashboard.html#saved', 3)}
      ${row('building', 'My listings', 'dashboard.html#listings', 2)}
      ${row('inbox', 'Enquiries received', 'dashboard.html#received', '1 new', '')}
      ${row('send', 'My enquiries', 'dashboard.html#sent', 2)}
      <div class="sep"></div>
      ${row('plus', 'Post a property', 'post-property.html')}
      ${portals ? `<div class="sep"></div><div class="lbl overline">Workspaces</div>${portals}` : ''}
      <div class="sep"></div>
      ${row('logout', 'Sign out', 'home-a.html')}
    </div>`;
  };

  FP.header = function (a = {}) {
    const role = a.role || 'visitor';
    const active = a.active || '';
    const signed = role !== 'visitor';
    const u = D.user;
    const nav = NAV.map(([k, l, h]) => `<a href="${h}"${k === active ? ' aria-current="page"' : ''}${k === 'ai' ? ' class="ai"' : ''}>${k === 'ai' ? icon('sparkle') : ''}${l}</a>`).join('');
    const right = signed
      ? `<a class="post" href="post-property.html">${icon('plus')}Post property</a>
         <a class="hdr-icon" href="dashboard.html#saved" aria-label="Saved homes, 3">${icon('heart')}<span class="dot">3</span></a>
         <button class="avatar-btn${a.menu ? ' is-hover' : ''}" type="button" aria-haspopup="menu" aria-expanded="${!!asBool(a.menu)}" aria-label="Account menu"><span class="avatar">${u.initials}</span>${icon('chev')}</button>`
      : `<a class="post" href="post-property.html">${icon('plus')}Post property</a><a class="signin" href="auth.html">Sign in</a>`;
    return `<a class="skip" href="#main">Skip to content</a>
    <header class="hdr${a.line ? ' line' : ''}" role="banner"><div class="container">
      <a class="logo" href="home-a.html" aria-label="Find Prop, home"><svg class="mark" aria-hidden="true"><use href="#logo-mark"/></svg><span>Find <b>Prop</b></span></a>
      <nav class="nav" aria-label="Main">${nav}</nav>
      <div class="hdr-r">${right}<button class="menu-btn" type="button" aria-label="Open menu" aria-haspopup="dialog">${icon('menu')}</button></div>
    </div>${asBool(a.menu) ? FP.accountMenu(role) : ''}</header>`;
  };

  FP.drawer = function (a = {}) {
    const role = a.role || 'visitor';
    const active = a.active || '';
    const signed = role !== 'visitor';
    const big = NAV.map(([k, l, h]) => `<a href="${h}"${k === active ? ' aria-current="page"' : ''}${k === 'ai' ? ' class="ai"' : ''}>${l}${icon('chev-r')}</a>`).join('');
    const u = D.user;
    const acct = signed
      ? `<div class="group"><span class="overline">Your account</span>
           <a class="link-row" href="dashboard.html#saved">${icon('heart')}Saved homes<span class="meta" style="background:var(--c-bg-sunken);color:var(--c-ink)">3</span></a>
           <a class="link-row" href="dashboard.html#listings">${icon('building')}My listings<span class="meta" style="background:var(--c-bg-sunken);color:var(--c-ink)">2</span></a>
           <a class="link-row" href="dashboard.html#received">${icon('inbox')}Enquiries received<span class="meta">1</span></a>
           <a class="link-row" href="dashboard.html#sent">${icon('send')}My enquiries</a></div>
         ${role === 'builder' ? `<div class="group"><span class="overline">Workspaces</span><a class="link-row" href="builder-dashboard.html">${icon('briefcase')}Builder portal</a></div>` : ''}
         ${role === 'admin' ? `<div class="group"><span class="overline">Workspaces</span><a class="link-row" href="admin-overview.html">${icon('layers')}Admin portal</a></div>` : ''}`
      : '';
    const cta = signed
      ? `<a class="btn btn--accent btn--block" href="post-property.html">${icon('plus')}Post a property</a><a class="btn btn--secondary btn--block" href="home-a.html">${icon('logout')}Sign out</a>`
      : `<a class="btn btn--accent btn--block" href="post-property.html">${icon('plus')}Post a property</a><a class="btn btn--primary btn--block" href="auth.html">Sign in</a><a class="btn btn--secondary btn--block" href="auth.html#signup">Create account</a>`;
    return `<div class="navdrawer" role="dialog" aria-modal="true" aria-label="Menu">
      <div class="top"><a class="logo" href="home-a.html"><svg class="mark" aria-hidden="true"><use href="#logo-mark"/></svg><span>Find <b>Prop</b></span></a><button class="icon-btn" type="button" aria-label="Close menu">${icon('x')}</button></div>
      ${signed ? `<div class="row" style="padding:8px 0 14px"><span class="avatar lg">${u.initials}</span><div><b>${u.name}</b><div class="small muted">${u.email}</div></div></div>` : ''}
      <nav class="big" aria-label="Main">${big}</nav>
      ${acct}
      <div class="cta">${cta}</div>
    </div>`;
  };

  FP.bottombar = function (a = {}) {
    const on = a.active || '';
    const it = (k, ic, l, h, extra = '') => `<a href="${h}" class="${k === 'post' ? 'post ' : ''}${on === k ? 'on' : ''}"${on === k ? ' aria-current="page"' : ''}>${icon(ic)}${l}${extra}</a>`;
    return `<nav class="bottombar" aria-label="Primary">${it('home', 'home', 'Home', 'home-a.html')}${it('search', 'search', 'Search', 'search.html')}${it('post', 'plus', 'Post', 'post-property.html')}${it('saved', 'heart', 'Saved', 'dashboard.html#saved', '<span class="badge-dot">3</span>')}${it('me', 'user', 'Me', 'dashboard.html#listings')}</nav>`;
  };

  FP.footer = function () {
    return `<footer class="ftr on-dark"><div class="container">
      <div class="ftr-grid">
        <div><a class="logo" href="home-a.html"><svg class="mark" aria-hidden="true"><use href="#logo-mark"/></svg><span>Find <b>Prop</b></span></a>
          <p>Search, shortlist and compare homes across Chennai, and enquire directly with owners and builders.</p></div>
        <div class="ftr-cols" style="display:contents">
          <div><h4>Explore</h4><ul><li><a href="search.html#buy">Buy a home</a></li><li><a href="search.html#rent">Rent a home</a></li><li><a href="projects.html">New projects</a></li><li><a href="ai-search.html">AI search</a></li></ul></div>
          <div><h4>For owners and builders</h4><ul><li><a href="post-property.html">Post a property</a></li><li><a href="dashboard.html#listings">My listings</a></li><li><a href="builder-login.html">Builder sign in</a></li><li><a href="contact.html">Contact us</a></li></ul></div>
        </div>
        <div><h4>Contact</h4>
          <div class="ci">${icon('phone')}<span>+91 90000 00000</span></div>
          <div class="ci">${icon('mail')}<span>hello@findprop.example</span></div>
          <div class="ci">${icon('pin')}<span>Chennai, Tamil Nadu</span></div></div>
      </div>
      <div class="ftr-bottom"><span>© 2026 Find Prop. Sample footer: content comes from the Footer CMS settings.</span><a href="contact.html">Contact</a></div>
    </div></footer>`;
  };

  /* ── Search card ──────────────────────────────── */
  FP.search = function (o = {}) {
    const layout = o.layout || 'wide';
    const intent = o.intent || 'buy';
    const f = (cls, key, lbl, val, ph, ic, chev, short) => `<label class="sf ${cls}${o.focus === key ? ' is-focus' : ''}${o.hover === key ? ' is-hover' : ''}"><span class="lbl"><span class="long">${lbl}</span><span class="short">${short || lbl}</span></span><span class="val">${ic ? icon(ic) : ''}${val ? `<span class="truncate">${val}</span>` : `<span class="ph truncate">${ph}</span>`}${chev ? icon('chev', 'chev') : ''}</span></label>`;
    const help = o.help === false ? '' : `<div class="s-help"><span>Popular</span>${D.popular.slice(0, layout === 'stacked' ? 3 : 4).map((p) => `<a class="chip" href="search.html">${p}</a>`).join('')}<span class="sep"></span><span>Quick picks</span><a class="chip" href="search.html">3 BHK</a><a class="chip" href="search.html">Budget homes</a></div>`;
    return `<section class="search search--${layout}" aria-label="Property search">
      <div class="s-top">
        <div class="seg" role="tablist" aria-label="Looking to"><button type="button" role="tab" aria-selected="${intent === 'buy'}" class="${intent === 'buy' ? 'on' : ''}">Buy</button><button type="button" role="tab" aria-selected="${intent === 'rent'}" class="${intent === 'rent' ? 'on' : ''}">Rent</button><a href="projects.html" role="tab" aria-selected="false">New projects ${icon('arrow')}</a></div>
        <a class="ai-link" href="ai-search.html">${icon('sparkle')}Describe it in words</a>
      </div>
      <div class="s-row">
        ${f('sf-loc', 'loc', 'Locality', o.loc, 'Search a locality', 'pin', false)}${f('sf-type', 'type', 'Property type', o.type, 'Any type', '', true, 'Type')}${f('sf-bhk', 'bhk', 'Bedrooms', o.bhk, 'Any BHK', '', true)}${f('sf-bud', 'bud', 'Max budget', o.budget, 'Any budget', '', true, 'Budget')}
        <button class="go${o.hover === 'go' ? ' is-hover' : ''}" type="button">${icon('search')}Search</button>
      </div>${help}${o.extra || ''}
    </section>`;
  };

  /* ── Cards ────────────────────────────────────── */
  FP.pcard = function (p, o = {}) {
    if (typeof p !== 'object') p = FP.byId(D.props, p);
    const specs = [p.bhk ? `<li>${icon('bed')}${p.bhk} BHK</li>` : '', p.bath ? `<li>${icon('bath')}${p.bath} Bath</li>` : '', p.area ? `<li>${icon('area')}${p.area} sq.ft</li>` : ''].join('');
    const badges = `<span class="badge badge--type">${p.lt === 'sale' ? 'For sale' : 'For rent'}</span>${p.label ? `<span class="badge badge--${p.label}">${cap(p.label)}</span>` : ''}`;
    const dots = o.dots === false ? '' : '<div class="pcard-dots"><i class="on"></i><i></i><i></i></div>';
    return `<article class="pcard${o.compared ? ' is-compared' : ''}${o.hover ? ' is-hover' : ''}${o.list ? ' pcard--list' : ''}">
      <div class="pcard-media">${FP.art(p.art[0], p.art[1], `Illustrated placeholder for ${p.t}`)}<div class="pcard-badges">${badges}</div>${dots}</div>
      <button class="pcard-save" type="button" aria-pressed="${!!o.saved}" aria-label="${o.saved ? 'Remove from saved homes' : 'Save to shortlist'}">${icon('heart')}</button>
      <div class="pcard-body">
        <div class="pcard-top"><div class="price num">${p.price}${p.per ? `<span class="per">${p.per}</span>` : ''}</div><span class="pcard-age">${p.age}</span></div>
        <h3 class="pcard-title ${o.list ? '' : 'clamp-2'}"><a class="stretched" href="property.html">${p.t}</a></h3>
        <div class="pcard-loc">${icon('pin')}<span class="truncate">${p.loc}, Chennai</span></div>
        ${specs ? `<ul class="pcard-specs">${specs}</ul>` : ''}
        ${o.list ? `<p class="desc clamp-2">${p.pt} in ${p.loc}${p.furn ? `, ${p.furn.toLowerCase()}` : ''}. Listed ${p.age}.</p>` : ''}
      </div>
      <div class="pcard-foot"><button class="cmp" type="button" aria-pressed="${!!o.compared}"${o.cmpDisabled ? ' disabled title="You can compare up to 3 homes"' : ''}><span class="box">${icon('check')}</span>${o.compared ? 'Added to compare' : 'Compare'}</button><span class="meta">${p.pt}</span></div>
    </article>`;
  };
  FP.pcardSkeleton = () => `<article class="pcard skeleton" aria-hidden="true"><div class="pcard-media"><div class="sk"></div></div><div class="pcard-body"><div class="sk line l" style="width:42%"></div><div class="sk line" style="width:92%"></div><div class="sk line" style="width:64%"></div><div class="sk line" style="width:78%;margin-top:6px"></div></div><div class="pcard-foot"><div class="sk line" style="width:90px"></div></div></article>`;

  FP.jcard = function (j) {
    if (typeof j !== 'object') j = FP.byId(D.projects, j);
    return `<article class="jcard"><div class="jcard-media">${FP.art(j.art[0], j.art[1], `Illustrated placeholder for ${j.name}`)}<div class="pcard-badges">${j.featured ? '<span class="badge badge--featured">Featured</span>' : ''}<span class="badge badge--type">${j.status}</span></div></div>
      <div class="jcard-body"><span class="jcard-builder">${j.builder}</span><h3 class="jcard-name"><a class="stretched" href="project.html">${j.name}</a></h3>
        <div class="pcard-loc">${icon('pin')}<span>${j.loc}, Chennai</span></div><div class="jcard-price num">${j.range}</div>
        <div class="jcard-chips">${j.bhk.map((b) => `<span class="tag">${b}</span>`).join('')}</div></div></article>`;
  };

  FP.tiles = function () {
    return `<div class="tiles">${D.tiles.map(([n, s, c], i) => `<a class="tile ${c}" href="search.html"><svg class="arch" viewBox="0 0 46 64" aria-hidden="true"><path d="M5 62V27a18 18 0 0 1 36 0V62" fill="none" stroke="${i % 2 ? '#9A4A20' : '#1F4A38'}" stroke-width="3" stroke-linecap="round"/><circle cx="23" cy="40" r="3.2" fill="${i % 2 ? '#9A4A20' : '#1F4A38'}"/></svg>${n}<small>${s}</small></a>`).join('')}</div>`;
  };

  FP.bcard = function (b) {
    return `<article class="bcard"><div class="head"><span class="mono ${b.cls}">${b.mono}</span><div><b>${b.name}</b><span>${b.count} projects</span></div></div><p>${b.about}</p>
      <div class="thumbs">${b.projects.map((id) => { const j = FP.byId(D.projects, id); return `<a class="thumb" href="project.html"><div class="ph">${FP.art(j.art[0], j.art[1], `Illustrated placeholder for ${j.name}`)}</div><span>${j.name}</span></a>`; }).join('')}</div></article>`;
  };

  FP.stat = function (label, value, o = {}) {
    const tag = o.href ? 'a' : 'div';
    return `<${tag} class="stat${o.attn ? ' attn' : ''}"${o.href ? ` href="${o.href}"` : ''}><div class="top"><span class="lbl">${label}</span>${o.icon ? `<span class="ic ${o.tone || ''}">${icon(o.icon)}</span>` : ''}</div><div class="val num">${value}</div>${o.sub ? `<div class="sub">${o.sub}</div>` : ''}</${tag}>`;
  };

  FP.gallery = function (o = {}) {
    const kinds = o.kinds || [['apartment', 1], ['living', 0], ['bedroom', 0], ['kitchen', 0], ['balcony', 1], ['floorplan', 0]];
    const act = o.active || 0;
    const label = (k) => ({ apartment: 'Exterior', lowrise: 'Exterior', twin: 'Exterior', villa: 'Exterior', house: 'Exterior', plot: 'Site', commercial: 'Exterior', living: 'Living room', bedroom: 'Bedroom', kitchen: 'Kitchen', balcony: 'View from the balcony', floorplan: 'Floor plan' }[k] || k);
    const [mk, mv] = kinds[act];
    return `<div class="gallery${o.bleed === false ? '' : ' bleed'}" aria-roledescription="carousel" aria-label="Photos">
      <div class="main">${FP.art(mk, mv, `Illustrated placeholder: ${label(mk)}`)}
        ${o.badges ? `<div class="pcard-badges">${o.badges}</div>` : ''}
        <button class="nav-btn prev" type="button" aria-label="Previous photo">${icon('chev-l')}</button><button class="nav-btn next" type="button" aria-label="Next photo">${icon('chev-r')}</button>
        <span class="count">${icon('image')} ${act + 1} / ${kinds.length}</span></div>
      <div class="thumbs">${kinds.map(([k, v], i) => `<button type="button" class="${i === act ? 'on' : ''}" aria-label="Photo ${i + 1}: ${label(k)}" aria-current="${i === act}">${FP.art(k, v)}</button>`).join('')}</div>
      <div class="dots" aria-hidden="true">${kinds.map((_, i) => `<i class="${i === act ? 'on' : ''}"></i>`).join('')}</div></div>`;
  };

  FP.cmpbar = function (o = {}) {
    const ids = list(o.ids).map(Number);
    const slots = [0, 1, 2].map((i) => ids[i] ? `<div class="slot full">${FP.art(FP.byId(D.props, ids[i]).art[0], FP.byId(D.props, ids[i]).art[1])}<span class="x">${icon('x')}</span></div>` : '<div class="slot"></div>').join('');
    return `<div class="cmpbar" role="region" aria-label="Compare homes"><div class="slots">${slots}</div>
      <div class="txt">${ids.length} of 3<span class="hide-m"> selected</span><small>${ids.length < 2 ? 'Choose at least 2 homes to compare' : 'You can compare up to 3 homes'}</small></div>
      <button class="btn btn--ghost btn--sm clear" type="button">Clear all</button>
      <a class="btn btn--primary btn--sm${ids.length < 2 ? ' is-disabled' : ''}" href="compare.html"${ids.length < 2 ? ' aria-disabled="true"' : ''}>Compare now ${icon('arrow')}</a></div>`;
  };

  /* ── Sponsored container: platform-owned frame and label, advertiser-owned image ── */
  const AD = {
    strip: { d: ['strip-970x90', 970, 90], m: ['strip-m-320x100', 320, 100] },
    inline: { d: ['strip-970x90', 970, 90], m: ['strip-m-320x100', 320, 100] },
    panel: { d: ['panel-524x494', 524, 494], m: ['panel-m-640x320', 640, 320] },
  };
  FP.sponsor = function (o = {}) {
    const fmt = o.format || 'strip';
    const c = o.creative || 'a';
    const n = Number(o.n || 1);
    const i = Number(o.i || 1);
    const spec = AD[fmt];
    const dSrc = o.src || `../assets/ads/${spec.d[0]}-${c}.svg`;
    const mSrc = o.srcM || `../assets/ads/${spec.m[0]}-${c}.svg`;
    const pager = n > 1 ? `<span class="sp-pager"><button class="pg" type="button" aria-label="Previous sponsored banner">${icon('chev-l')}</button><span class="n">${i} / ${n}</span><button class="pg" type="button" aria-label="Next sponsored banner">${icon('chev-r')}</button></span>` : '';
    const info = asBool(o.info) ? `<div class="popover" style="position:absolute;right:0;top:30px;z-index:5;width:300px"><b>About sponsored content</b><br>This banner is a paid placement from an advertiser. <span class="flag">Wording to be approved</span></div>` : '';
    const cls = `sp sp--${fmt}`;
    return `<aside class="${cls}" aria-label="Sponsored">
      <div class="sp-meta"><span class="sp-label">Sponsored<span class="sample">Sample ad</span></span><span class="sp-ctl"><button type="button" aria-label="About this sponsored banner">${icon('info')}About this ad</button>${pager}</span></div>
      <a class="sp-frame${asBool(o.contain) ? ' is-contain' : ''}${asBool(o.loading) ? ' is-loading' : ''}" href="#" target="_blank" rel="sponsored noopener" aria-label="Sponsored banner (opens the advertiser's page in a new tab)">
        ${asBool(o.loading) ? '' : `<picture><source media="(max-width: 1023px)" srcset="${mSrc}"><img src="${dSrc}" width="${spec.d[1]}" height="${spec.d[2]}" alt="Sample advertiser banner, ${c.toUpperCase()}"></picture>`}</a>${info}</aside>`;
  };

  /* ── Home page sections shared by all three hero variations ── */
  FP.homeBelow = function () {
    const row = (ids, o) => ids.map((id) => FP.pcard(id, o && o[id])).join('');
    return `
    <section class="section"><div class="container">
      <div class="sect-head"><h2 class="h2">Explore by locality</h2><a class="link-arrow" href="search.html">See all localities ${icon('arrow')}</a></div>
      ${FP.tiles()}
    </div></section>

    <section class="section tight"><div class="container">
      <div class="sect-head"><h2 class="h2">Featured homes</h2><a class="link-arrow" href="search.html">View all ${icon('arrow')}</a></div>
      <div class="cards c3">${row([1, 3, 7, 2, 6, 9], { 1: { saved: true } })}</div>
    </div></section>

    <section class="section band"><div class="container">
      <div class="sect-head"><div><h2 class="h2">New launches from developers</h2><p class="muted mt-1">Approved and published projects only.</p></div><a class="link-arrow" href="projects.html">See all projects ${icon('arrow')}</a></div>
      <div class="cards c3">${D.builders.map(FP.bcard).join('')}</div>
    </div></section>

    <section class="section"><div class="container">
      <div class="sect-head"><h2 class="h2">Browse by what matters</h2></div>
      <div class="cat-grid">
        <a class="catcard" href="search.html">${icon('star')}<b>Featured</b><span>Hand-picked homes we recommend first</span>${icon('arrow', 'go')}</a>
        <a class="catcard" href="search.html">${icon('building')}<b>Prime</b><span>Premium addresses and large luxury homes</span>${icon('arrow', 'go')}</a>
        <a class="catcard" href="search.html">${icon('tag')}<b>Budget</b><span>Affordable homes that fit a smaller budget</span>${icon('arrow', 'go')}</a>
        <a class="catcard" href="search.html">${icon('pin')}<b>By locality</b><span>Browse homes area by area across Chennai</span>${icon('arrow', 'go')}</a>
      </div>
    </div></section>

    <section class="section tight"><div class="container">
      <div class="sect-head"><h2 class="h2">Newest on Find Prop</h2><div class="row gap-2 hide-m"><button class="icon-btn" type="button" aria-label="Previous">${icon('chev-l')}</button><button class="icon-btn" type="button" aria-label="Next">${icon('chev-r')}</button></div></div>
      <div class="hscroll">${row([6, 4, 12, 5, 9])}</div>
    </div></section>

    <section class="section"><div class="container">
      <div class="sect-head"><h2 class="h2">Why <em>Find Prop</em></h2></div>
      <div class="value-grid">
        <div class="valuecard"><span class="ic">${icon('shield')}</span><b>Approved listings only</b><p>Homes appear on Find Prop after they are approved.</p></div>
        <div class="valuecard"><span class="ic">${icon('msg')}</span><b>Enquire directly</b><p>Send your details to the owner or builder, and track the reply in your dashboard.</p></div>
        <div class="valuecard"><span class="ic">${icon('cols')}</span><b>Shortlist and compare</b><p>Save homes you like and compare up to three side by side.</p></div>
      </div>
    </div></section>

    <section class="section tight"><div class="container">
      <div class="ctaband"><div><h2 class="h2" style="color:#fff">Want to sell or rent your property?</h2><p>Post your property free. Your listing is reviewed, then goes live.</p></div><a class="btn btn--accent btn--lg" href="post-property.html">${icon('plus')}Post your property free</a></div>
    </div></section>`;
  };

  /* ── Custom tags → components ── */
  T.header = (a) => FP.header(a);
  T.footer = () => FP.footer();
  T.bottombar = (a) => FP.bottombar(a);
  T.drawer = (a) => FP.drawer(a);
  T.search = (a) => FP.search(a);
  T.sponsor = (a) => FP.sponsor(a);
  T.homebelow = () => FP.homeBelow();
  T.cmpbar = (a) => FP.cmpbar(a);
  T.accountmenu = (a) => FP.accountMenu(a.role || 'user');
  T.cards = (a) => {
    const ids = list(a.ids);
    const saved = list(a.saved);
    const cmp = list(a.compared);
    const cls = a.cols ? ` ${a.cols}` : '';
    const cmpFull = cmp.length >= 3;
    const adAfter = Number(a.adAfter || 0);
    const ad = adAfter ? `<div class="cards-ad">${FP.sponsor({ format: 'inline', creative: a.adCreative || 'b' })}</div>` : '';
    const html = ids.map((id) => FP.pcard(id, { saved: saved.includes(id), compared: cmp.includes(id), cmpDisabled: cmpFull && !cmp.includes(id), list: asBool(a.list) }));
    if (adAfter) html.splice(adAfter, 0, ad);
    return `<div class="cards${cls}${asBool(a.list) ? ' list' : ''}">${html.join('')}</div>`;
  };
  T.skeletons = (a) => `<div class="cards${a.cols ? ' ' + a.cols : ''}">${Array.from({ length: Number(a.n || 6) }, FP.pcardSkeleton).join('')}</div>`;
  T.projects = (a) => `<div class="cards${a.cols ? ' ' + a.cols : ''}">${list(a.ids).map((id) => FP.jcard(id)).join('')}</div>`;
  T.gallery = (a) => {
    const b = list(a.badges).map((k) => (k === 'sale' ? '<span class="badge badge--type">For sale</span>' : k === 'rent' ? '<span class="badge badge--type">For rent</span>' : `<span class="badge badge--${k}">${cap(k)}</span>`)).join('');
    const kinds = a.kinds ? a.kinds.split(',').map((k) => { const [n, v] = k.split(':'); return [n, Number(v || 0)]; }) : undefined;
    return FP.gallery({ badges: b, kinds, active: Number(a.active || 0), bleed: a.bleed === 'false' ? false : true });
  };
  T.tiles = () => FP.tiles();
  T.arches = (a) => FP.arches(a.pos);
  T.stat = (a) => FP.stat(a.label, a.value, { icon: a.icon, tone: a.tone, sub: a.sub, href: a.href, attn: asBool(a.attn) });
  T.icon = (a) => icon(a.n, a.class || '');
  T.art = (a) => FP.art(a.kind, Number(a.v || 0), a.alt || '');

  FP.mount = function () {
    for (let guard = 0; guard < 6; guard++) {
      const els = [...document.querySelectorAll('*')].filter((e) => e.localName.startsWith('fp-') && T[e.localName.slice(3)]);
      if (!els.length) break;
      els.forEach((el) => {
        const a = {};
        for (const at of el.attributes) a[at.name.replace(/-([a-z])/g, (_, c) => c.toUpperCase())] = at.value;
        const html = T[el.localName.slice(3)](a, el);
        const keep = ['data-show', 'data-hide'].filter((k) => el.hasAttribute(k)).map((k) => `${k}="${el.getAttribute(k)}"`).join(' ');
        el.outerHTML = keep ? `<div style="display:contents" ${keep}>${html}</div>` : html;
      });
    }
  };

  /* ── #state: show/hide blocks, tabs and spec overlay from the URL hash ── */
  FP.applyState = function () {
    const def = document.body.dataset.default || 'default';
    const raw = decodeURIComponent(location.hash.replace(/^#/, ''));
    const tokens = (raw ? raw.split(',') : def.split(',')).map((s) => s.trim()).filter(Boolean);
    document.documentElement.dataset.tokens = tokens.join(' ');
    document.querySelectorAll('[data-show]').forEach((el) => { el.hidden = !el.dataset.show.split(/\s+/).some((t) => t === '*' || tokens.includes(t)); });
    document.querySelectorAll('[data-hide]').forEach((el) => { if (el.dataset.hide.split(/\s+/).some((t) => tokens.includes(t))) el.hidden = true; });
    document.querySelectorAll('[data-tab]').forEach((el) => { const on = tokens.includes(el.dataset.tab); el.classList.toggle('on', on); if (on) el.setAttribute('aria-current', 'page'); else el.removeAttribute('aria-current'); });
    document.querySelectorAll('[data-off]').forEach((el) => { if (el.dataset.off.split(/\s+/).some((t) => tokens.includes(t))) { el.classList.remove('on'); el.removeAttribute('aria-current'); } });
    if (tokens.includes('spec')) FP.measure();
    return tokens;
  };

  /* Spec overlay: label each [data-dim] box with its measured rendered size, so the numbers are real, not typed. */
  FP.measure = function () {
    const run = () => document.querySelectorAll('[data-dim]').forEach((box) => {
      const host = box.parentElement;
      const tgt = box.dataset.target ? host.querySelector(box.dataset.target) : host;
      const r = tgt.getBoundingClientRect();
      if (box.dataset.target) { const h = host.getBoundingClientRect(); Object.assign(box.style, { inset: 'auto', left: (r.left - h.left - 4) + 'px', top: (r.top - h.top - 4) + 'px', width: (r.width + 8) + 'px', height: (r.height + 8) + 'px' }); }
      const b = box.querySelector('b') || box.appendChild(document.createElement('b'));
      b.textContent = `${box.dataset.dim} · ${Math.round(r.width)} × ${Math.round(r.height)}`;
    });
    run();
    window.addEventListener('resize', run);
  };

  function behaviours() {
    document.addEventListener('click', (e) => {
      const save = e.target.closest('.pcard-save');
      if (save) { const on = save.getAttribute('aria-pressed') !== 'true'; save.setAttribute('aria-pressed', on); e.preventDefault(); return; }
      const cmp = e.target.closest('.cmp:not([disabled])');
      if (cmp) { const on = cmp.getAttribute('aria-pressed') !== 'true'; cmp.setAttribute('aria-pressed', on); cmp.closest('.pcard')?.classList.toggle('is-compared', on); e.preventDefault(); return; }
      const seg = e.target.closest('.seg button');
      if (seg) { seg.parentElement.querySelectorAll('button').forEach((b) => { b.classList.toggle('on', b === seg); b.setAttribute('aria-selected', b === seg); }); return; }
      const chip = e.target.closest('button.chip');
      if (chip) {
        const row = chip.closest('.chip-row.single');
        if (row) row.querySelectorAll('button.chip').forEach((b) => { b.classList.toggle('on', b === chip); b.setAttribute('aria-pressed', b === chip); });
        else { chip.classList.toggle('on'); chip.setAttribute('aria-pressed', chip.classList.contains('on')); }
      }
    });
  }

  function init() {
    if (!document.getElementById('fp-sprite')) {
      const holder = document.createElement('div');
      holder.id = 'fp-sprite';
      holder.innerHTML = FP.sprite();
      document.body.prepend(holder);
    }
    FP.mount();
    FP.applyState();
    if (FP.renderCharts) { const hv = document.documentElement.dataset.tokens.split(' ').includes('hover') ? 18 : null; FP.setHover(hv); FP.renderCharts(hv); window.addEventListener('hashchange', () => FP.renderCharts(document.documentElement.dataset.tokens.split(' ').includes('hover') ? 18 : null)); }
    window.addEventListener('hashchange', FP.applyState);
    behaviours();
    document.documentElement.classList.add('fp-ready');
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();

/* ===== fp-pages.js ===== */
/* Find Prop — page-level components reused by more than one screen (filters, enquiry card, form pieces, portal shell, charts).
   Loaded after fp-ui.js. */
window.FP = window.FP || {};
(function () {
  const icon = FP.icon;
  const D = FP.data;
  const T = FP.tags;
  const asBool = (v) => v === '' || v === true || v === 'true';
  const opts = (arr, sel) => arr.map((o) => `<option${o === sel ? ' selected' : ''}>${o}</option>`).join('');

  /* Search filters: the same fields as the homepage search card, plus sort and label, as a rail (desktop) or sheet (mobile) */
  FP.filters = function (o = {}) {
    const rent = o.intent === 'rent';
    const P = o.sheet ? 'fs' : 'f';
    const chips = ['Any', '1', '2', '3', '4'].map((b) => `<button type="button" class="chip${b === (o.bhk || 'Any') ? ' on' : ''}" aria-pressed="${b === (o.bhk || 'Any')}">${b}</button>`).join('');
    return `<div class="filter-panel">
      <div class="row between"><h2 class="title">Filters</h2><a class="link small" href="#">Clear all</a></div>
      <div class="field"><span class="label">Looking to</span><div class="seg seg--block" role="tablist"><button type="button" role="tab" class="${!o.intent ? 'on' : ''}">All</button><button type="button" role="tab" class="${o.intent === 'buy' ? 'on' : ''}">Buy</button><button type="button" role="tab" class="${rent ? 'on' : ''}">Rent</button></div></div>
      <div class="field"><label class="label" for="${P}-loc">Locality</label><select id="${P}-loc" class="select">${opts(['All of Chennai'].concat(D.localities), o.loc || 'All of Chennai')}</select></div>
      <div class="field"><label class="label" for="${P}-type">Property type</label><select id="${P}-type" class="select">${opts(['Any type'].concat(D.types), o.type || 'Any type')}</select></div>
      <div class="field"><span class="label">Bedrooms (BHK)</span><div class="chip-row single grid5">${chips}</div></div>
      <div class="field"><label class="label" for="${P}-bud">Max budget</label><select id="${P}-bud" class="select">${opts(rent ? D.budgetRent : D.budgetSale, o.budget || (rent ? D.budgetRent[0] : D.budgetSale[0]))}</select></div>
      ${o.sheet ? `<div class="field"><label class="label" for="${P}-sort">Sort by</label><select id="${P}-sort" class="select">${opts(['Newest', 'Price: low to high', 'Price: high to low', 'Largest first'])}</select></div>` : ''}
    </div>`;
  };
  T.filters = (a) => FP.filters({ intent: a.intent, loc: a.loc, type: a.type, bhk: a.bhk, budget: a.budget, sheet: asBool(a.sheet) });

  /* Pager / pagination note */
  FP.loadmore = (shown, total) => `<div class="loadmore"><span>Showing ${shown} of ${total} homes</span><div class="bar"><i style="width:${Math.round((shown / total) * 100)}%"></i></div><button class="btn btn--secondary" type="button">Show more homes</button></div>`;
  T.loadmore = (a) => FP.loadmore(a.shown, a.total);
})();

/* ===== fp-charts.js ===== */
/* Find Prop — charts (inline SVG/HTML, no library). Built to the dataviz method:
   2 px lines, ≥ 8 px end dots with a 2 px surface ring, hairline grid, 4 px rounded bar ends, 2 px surface gaps,
   text in ink tokens (never series colour), legend for ≥ 2 series, crosshair + one tooltip for all series, table view.
   Series colours come from the validated --c-series-* tokens, assigned in fixed order. */
window.FP = window.FP || {};
(function () {
  const REG = {};
  let cid = 0;
  const fmt = (v) => Number(v).toLocaleString('en-IN');
  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  const COLORS = ['var(--c-series-1)', 'var(--c-series-2)', 'var(--c-series-3)', 'var(--c-series-4)'];

  /** Multi- or single-series line chart. o = {labels, series:[{name,data}], yMax, yMin, ticks, w, h, area, endLabels, tickEvery, unit} */
  FP.line = function (o) {
    const id = ++cid;
    HOSTS[id] = o;
    return `<div class="chart-host" data-lid="${id}" style="min-height:${o.h || 260}px"></div>`;
  };
  const HOSTS = {};
  FP.lineSVG = function (o) {
    const w = o.w || 640, h = o.h || 260;
    const m = { l: 44, r: o.endLabels === false ? 16 : 104, t: 14, b: 30 };
    const pw = w - m.l - m.r, ph = h - m.t - m.b;
    const n = o.labels.length;
    const yMin = o.yMin || 0, yMax = o.yMax;
    const X = (i) => m.l + (n === 1 ? pw / 2 : (i * pw) / (n - 1));
    const Y = (v) => m.t + ph - ((v - yMin) / (yMax - yMin)) * ph;
    const id = ++cid;
    REG[id] = { labels: o.labels, series: o.series.map((s, i) => ({ name: s.name, data: s.data, color: COLORS[(s.slot || i + 1) - 1] })), unit: o.unit || '', X: o.labels.map((_, i) => X(i)), Y, w, h, m };
    const ticks = o.ticks || [yMin, yMax];
    const grid = ticks.map((t) => `<line class="grid" x1="${m.l}" x2="${w - m.r}" y1="${Y(t)}" y2="${Y(t)}"/><text x="${m.l - 10}" y="${Y(t) + 4}" text-anchor="end">${fmt(t)}</text>`).join('');
    const every = o.tickEvery || Math.ceil(n / 6);
    const xl = o.labels.map((l, i) => (i % every === 0 ? `<text x="${X(i)}" y="${h - 8}" text-anchor="middle">${esc(l)}</text>` : '')).join('');
    const col = (i) => COLORS[(o.series[i].slot || i + 1) - 1];
    const lines = o.series.map((s, i) => {
      const d = s.data.map((v, k) => `${k ? 'L' : 'M'}${X(k).toFixed(1)} ${Y(v).toFixed(1)}`).join('');
      const area = o.area ? `<path d="${d}L${X(n - 1)} ${Y(yMin)}L${X(0)} ${Y(yMin)}Z" fill="${col(i)}" opacity=".1"/>` : '';
      const lx = X(n - 1), ly = Y(s.data[n - 1]);
      const dot = `<circle cx="${lx}" cy="${ly}" r="6" fill="var(--c-surface)"/><circle cx="${lx}" cy="${ly}" r="4" fill="${col(i)}"/>`;
      const lab = o.endLabels === false ? '' : `<text x="${lx + 14}" y="${ly + 4}"><tspan font-weight="700" style="fill:var(--c-ink)">${fmt(s.data[n - 1])}${o.unit || ''}</tspan><tspan dx="5">${esc(s.name)}</tspan></text>`;
      return `${area}<path d="${d}" fill="none" stroke="${col(i)}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>${dot}${lab}`;
    }).join('');
    const hov = `<line class="xhair" x1="0" x2="0" y1="${m.t}" y2="${m.t + ph}" hidden/>${o.series.map((_, i) => `<g class="hdot" hidden data-i="${i}"><circle r="6" fill="var(--c-surface)"/><circle r="4" fill="${col(i)}"/></g>`).join('')}`;
    const label = `${o.title || 'Line chart'}: ${o.series.map((s) => s.name).join(', ')}`;
    const legend = o.series.length > 1 ? `<div class="legend" style="margin-top:12px">${o.series.map((s, i) => `<span><i class="line" style="background:${col(i)}"></i>${esc(s.name)}</span>`).join('')}</div>` : '';
    return `<div class="chart-wrap" data-cid="${id}"><svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}" tabindex="0">${grid}<line class="axis" x1="${m.l}" x2="${w - m.r}" y1="${Y(yMin)}" y2="${Y(yMin)}"/>${xl}${lines}${hov}<rect class="hit" x="${m.l}" y="${m.t}" width="${pw}" height="${ph}" fill="transparent"/></svg><div class="tt" role="status" hidden></div>${legend}</div>`;
  };

  /** Horizontal bars, one series (nominal categories share slot 1). rows = [[label, value]] */
  FP.hbars = function (rows, o = {}) {
    const max = o.max || Math.max(...rows.map((r) => r[1]));
    return `<div class="hbars" role="img" aria-label="${esc(o.title || 'Bar chart')}">${rows.map(([l, v]) => `<div class="hb" tabindex="0" title="${esc(l)}: ${fmt(v)}"><span class="l">${esc(l)}</span><span class="bw"><i style="width:${Math.max(2, (v / max) * 100).toFixed(1)}%"></i><b class="num">${fmt(v)}</b></span></div>`).join('')}</div>`;
  };

  /** Part-to-whole: one stacked bar with 2 px gaps + a legend table. parts = [[name, value]] (≤ 4, then "Other") */
  FP.share = function (parts) {
    const total = parts.reduce((a, p) => a + p[1], 0);
    const colors = parts.map((_, i) => (parts[i][0] === 'Other' ? 'var(--c-series-other)' : COLORS[i]));
    const bar = parts.map((p, i) => `<i style="flex:${p[1]};background:${colors[i]}" title="${esc(p[0])}: ${fmt(p[1])}"></i>`).join('');
    const rows = parts.map((p, i) => `<tr><td><span class="sw" style="background:${colors[i]}"></span>${esc(p[0])}</td><td class="r num">${fmt(p[1])}</td><td class="r num muted">${Math.round((p[1] / total) * 100)}%</td></tr>`).join('');
    return `<div class="share" role="img" aria-label="Share by source: ${parts.map((p) => `${p[0]} ${Math.round((p[1] / total) * 100)} percent`).join(', ')}"><div class="sbar">${bar}</div><table class="stbl"><tbody>${rows}</tbody></table></div>`;
  };

  /** Plain table twin of a line chart (the accessible alternative). */
  FP.lineTable = function (o) {
    const r = o.labels.map((l, i) => `<tr><th scope="row">${esc(l)}</th>${o.series.map((s) => `<td class="r num">${fmt(s.data[i])}${o.unit || ''}</td>`).join('')}</tr>`).join('');
    return `<div class="tbl-scroll" style="max-height:280px;overflow:auto"><table class="tbl" style="min-width:0"><thead><tr><th>${o.xName || 'Date'}</th>${o.series.map((s) => `<th class="r">${esc(s.name)}</th>`).join('')}</tr></thead><tbody>${r}</tbody></table></div>`;
  };

  function show(wrap, idx) {
    const c = REG[wrap.dataset.cid];
    const svg = wrap.querySelector('svg');
    const sx = svg.getBoundingClientRect().width / c.w;
    const xh = svg.querySelector('.xhair');
    xh.setAttribute('x1', c.X[idx]); xh.setAttribute('x2', c.X[idx]); xh.hidden = false;
    svg.querySelectorAll('.hdot').forEach((g, i) => { g.hidden = false; g.setAttribute('transform', `translate(${c.X[idx]} ${c.Y(c.series[i].data[idx])})`); });
    const tt = wrap.querySelector('.tt');
    tt.replaceChildren();
    const t = document.createElement('div'); t.className = 'tt-h'; t.textContent = c.labels[idx]; tt.appendChild(t);
    c.series.forEach((s) => {
      const row = document.createElement('div'); row.className = 'tt-r';
      const key = document.createElement('i'); key.style.background = s.color;
      const v = document.createElement('b'); v.textContent = fmt(s.data[idx]) + c.unit;
      const n = document.createElement('span'); n.textContent = s.name;
      row.append(key, v, n); tt.appendChild(row);
    });
    tt.hidden = false;
    const left = c.X[idx] * sx;
    const w = tt.offsetWidth;
    tt.style.left = Math.min(Math.max(left + 14, 0), svg.getBoundingClientRect().width - w) + 'px';
    tt.style.top = '8px';
    wrap.dataset.idx = idx;
  }
  function hide(wrap) { wrap.querySelector('.tt').hidden = true; wrap.querySelector('.xhair').hidden = true; wrap.querySelectorAll('.hdot').forEach((g) => (g.hidden = true)); }

  /* Charts are drawn at their real pixel width so text stays 12 px at every viewport; redrawn on resize. */
  FP.renderCharts = function (hoverIdx) {
    document.querySelectorAll('.chart-host[data-lid]').forEach((host) => {
      const o = HOSTS[host.dataset.lid];
      const width = Math.round(host.getBoundingClientRect().width);
      if (!width) return;
      if (host.dataset.w === String(width)) return;
      host.dataset.w = width;
      const h = Math.round(Math.min(o.h || 260, Math.max(190, width * 0.42)));
      const compact = width < 480;
      host.innerHTML = FP.lineSVG({ ...o, w: width, h, endLabels: compact ? false : o.endLabels, tickEvery: compact ? Math.ceil(o.labels.length / 4) : o.tickEvery });
      host.style.minHeight = '';
    });
    FP.wireCharts(hoverIdx);
  };
  let lastHover = null, rz;
  window.addEventListener('resize', () => { clearTimeout(rz); rz = setTimeout(() => FP.renderCharts(lastHover), 120); });
  FP.setHover = (i) => { lastHover = i; };

  FP.wireCharts = function (hoverIdx) {
    document.querySelectorAll('.chart-wrap[data-cid]').forEach((wrap) => {
      if (wrap.dataset.wired === '1') { if (hoverIdx != null) show(wrap, Math.min(hoverIdx, REG[wrap.dataset.cid].labels.length - 1)); return; }
      wrap.dataset.wired = '1';
      const c = REG[wrap.dataset.cid];
      const svg = wrap.querySelector('svg');
      const idxAt = (clientX) => { const r = svg.getBoundingClientRect(); const x = ((clientX - r.left) / r.width) * c.w; let best = 0; c.X.forEach((px, i) => { if (Math.abs(px - x) < Math.abs(c.X[best] - x)) best = i; }); return best; };
      svg.addEventListener('pointermove', (e) => show(wrap, idxAt(e.clientX)));
      svg.addEventListener('pointerleave', () => hide(wrap));
      svg.addEventListener('keydown', (e) => { const i = Number(wrap.dataset.idx ?? c.labels.length - 1); if (e.key === 'ArrowLeft') { e.preventDefault(); show(wrap, Math.max(0, i - 1)); } if (e.key === 'ArrowRight') { e.preventDefault(); show(wrap, Math.min(c.labels.length - 1, i + 1)); } if (e.key === 'Escape') hide(wrap); });
      svg.addEventListener('focus', () => show(wrap, c.labels.length - 1));
      svg.addEventListener('blur', () => hide(wrap));
      if (hoverIdx != null && wrap.dataset.hover !== 'off') show(wrap, Math.min(hoverIdx, c.labels.length - 1));
    });
  };
})();

/* ===== fp-portal.js ===== */
/* Find Prop — portal shell shared by the admin and builder areas.
   One component, two navigation sets. Admin and builder screens that Phase 1 says share components (projects, units,
   leads, insights) are built from the same functions below with a `mode`, as in the existing product. */
window.FP = window.FP || {};
(function () {
  const icon = FP.icon;
  const T = FP.tags;
  const asBool = (v) => v === '' || v === true || v === 'true';

  const ADMIN = [
    ['', [['overview', 'Overview', 'dash', 'admin-overview.html']]],
    ['Moderation', [['listings', 'Listings', 'tag', 'admin-listings.html', { meta: 14, proposed: true }], ['projects', 'Projects', 'building', 'admin-projects.html', { meta: 3 }]]],
    ['Inventory', [['units', 'Units', 'layers', 'admin-units.html'], ['builders', 'Builders', 'briefcase', 'admin-builders.html']]],
    ['Leads and CRM', [['leads', 'Leads', 'inbox', 'admin-leads.html'], ['forms', 'Forms', 'forms', 'admin-forms.html'], ['crm', 'CRM', 'plug', 'admin-crm.html']]],
    ['Site content', [['cms-header', 'Header', 'layout', 'admin-cms.html#header'], ['cms-hero', 'Hero', 'image', 'admin-cms.html#hero'], ['cms-homepage', 'Homepage', 'home', 'admin-cms.html#homepage'], ['cms-footer', 'Footer', 'file', 'admin-cms.html#footer']]],
  ];
  const BUILDER = [
    ['', [['dashboard', 'Dashboard', 'dash', 'builder-dashboard.html'], ['projects', 'Projects', 'building', 'builder-projects.html'], ['units', 'Units', 'layers', 'builder-units.html'], ['leads', 'Leads', 'inbox', 'builder-leads.html'], ['insights', 'Insights', 'chart', 'builder-insights.html'], ['profile', 'Profile', 'user', 'builder-profile.html']]],
  ];

  FP.sidebar = function (role, active, inDrawer) {
    const sets = role === 'admin' ? ADMIN : BUILDER;
    const nav = sets.map(([label, items]) => `${label ? `<div class="side-label">${label}</div>` : ''}${items.map(([k, l, ic, href, o = {}]) => `<a class="side-link" href="${href}"${k === active ? ' aria-current="page"' : ''} title="${l}">${icon(ic)}<span class="t">${l}</span>${o.proposed ? '<span class="tag-proposed">Proposed</span>' : ''}${o.meta ? `<span class="meta">${o.meta}</span>` : ''}</a>`).join('')}`).join('');
    return `<aside class="sidebar on-dark${inDrawer ? ' in-drawer' : ''}" aria-label="${role === 'admin' ? 'Admin' : 'Builder'} navigation">
      <div class="brand"><a class="logo" href="home-a.html" aria-label="Find Prop"><svg class="mark" aria-hidden="true"><use href="#logo-mark"/></svg><span>Find <b>Prop</b></span></a><span class="portal-tag">${role === 'admin' ? 'Admin' : 'Builder'}</span></div>
      <nav>${nav}</nav>
      <div class="foot"><a class="side-link" href="home-a.html">${icon('ext')}<span class="t">View public site</span></a><a class="side-link" href="${role === 'admin' ? 'auth.html' : 'builder-login.html'}">${icon('logout')}<span class="t">Sign out</span></a></div>
    </aside>`;
  };

  FP.portal = function (a, inner) {
    const role = a.role || 'admin';
    const who = role === 'admin' ? { i: 'SA', n: 'Super admin' } : { i: 'KH', n: 'Kadal Homes' };
    return `<a class="skip" href="#main">Skip to content</a>
    <div class="portal">
      ${FP.sidebar(role, a.active)}
      <div class="pmain">
        <header class="ptop"><button class="menu-btn" type="button" aria-label="Open navigation" aria-haspopup="dialog">${icon('menu')}</button>
          <a class="logo" href="home-a.html"><svg class="mark" aria-hidden="true"><use href="#logo-mark"/></svg><span>Find <b>Prop</b></span></a>
          <span class="role-chip${role === 'admin' ? ' admin' : ''}" style="margin:0">${role === 'admin' ? 'Admin' : 'Builder'}</span>
          <div class="right"><a class="viewsite" href="home-a.html">View public site${icon('ext')}</a>
            <button class="avatar-btn" type="button" aria-haspopup="menu" aria-label="Account menu"><span class="avatar${role === 'admin' ? '' : ' copper'}">${who.i}</span>${icon('chev')}</button></div></header>
        <main id="main" class="pbody">${inner}</main>
      </div>
    </div>
    ${asBool(a.drawer) ? `<div class="scrim right" style="justify-content:start;place-items:stretch start" role="dialog" aria-modal="true" aria-label="Navigation">${FP.sidebar(role, a.active, true)}</div>` : ''}`;
  };
  T.portal = (a, el) => FP.portal(a, el.innerHTML);
  T.sidebar = (a) => FP.sidebar(a.role || 'admin', a.active, false);
  T.portaldrawer = (a) => `<div class="scrim right" style="place-items:stretch start" role="dialog" aria-modal="true" aria-label="Navigation">${FP.sidebar(a.role || 'admin', a.active, true)}</div>`;
})();

/* ===== fp-portal2.js ===== */
/* Find Prop — portal pages that admin and builder share (Phase 1: ProjectsManager, UnitsManager, LeadsTable, InsightsPanel).
   Each takes mode = 'admin' | 'builder'; the data scope is enforced by the backend, the UI only hides what the role cannot do. */
window.FP = window.FP || {};
(function () {
  const I = FP.icon;
  const T = FP.tags;
  const MOD = {
    pending: '<span class="badge badge--warning dot">Pending</span>', approved: '<span class="badge badge--success dot">Approved</span>',
    rejected: '<span class="badge badge--danger dot">Rejected</span>', draft: '<span class="badge badge--neutral dot">Draft</span>',
  };
  const PROJ = [
    { n: 'Kadal Vista', b: 'Kadal Homes', l: 'OMR Navalur', p: '₹78 L – ₹1.42 Cr', mod: 'approved', pub: true, feat: true, art: ['twin', 1], leads: 128 },
    { n: 'Nila Grove', b: 'Nila Habitats', l: 'Medavakkam', p: '₹62 L – ₹98 L', mod: 'pending', pub: false, art: ['lowrise', 0], leads: 12 },
    { n: 'Thendral Residency', b: 'Thendral Estates', l: 'Porur', p: '₹88 L – ₹1.3 Cr', mod: 'approved', pub: false, art: ['twin', 2], leads: 0 },
    { n: 'Arivu Heights', b: 'Arivu Constructions', l: 'Velachery', p: '₹1.1 Cr – ₹1.9 Cr', mod: 'approved', pub: true, feat: true, art: ['apartment', 4], leads: 96 },
    { n: 'Kadal Courts', b: 'Kadal Homes', l: 'OMR Siruseri', p: '₹54 L – ₹86 L', mod: 'pending', pub: false, art: ['commercial', 1], leads: 0 },
    { n: 'Nila Meadows', b: 'Nila Habitats', l: 'Guindy', p: '₹1.4 Cr – ₹2.2 Cr', mod: 'rejected', pub: false, art: ['villa', 1], leads: 21 },
  ];

  /* ── Projects (P-15 admin, P-26 builder) ── */
  FP.projectsPage = function (mode) {
    const admin = mode === 'admin';
    const rows = (admin ? PROJ : PROJ.filter((p) => p.b === 'Kadal Homes').concat([{ n: 'Kadal Bay', b: 'Kadal Homes', l: 'OMR Navalur', p: '₹70 L – ₹1.1 Cr', mod: 'draft', pub: false, art: ['twin', 0], leads: 0 }])).map((p, i) => {
      const flags = `${MOD[p.mod]}${p.mod === 'approved' ? (p.pub ? '<span class="badge badge--primary">Published</span>' : '<span class="badge badge--type">Unpublished</span>') : ''}${p.feat ? `<span class="badge badge--featured">${I('star')}Featured</span>` : ''}`;
      let acts = '';
      if (admin) {
        const main = p.mod === 'pending' ? `<button class="btn btn--primary btn--sm" type="button">${I('check')}Approve</button><button class="btn btn--danger-outline btn--sm" type="button">${I('x')}Reject</button>`
          : p.mod === 'rejected' ? `<button class="btn btn--secondary btn--sm" type="button">${I('check')}Approve</button>`
          : p.mod === 'approved' ? (p.pub ? '<button class="btn btn--secondary btn--sm" type="button">Unpublish</button>' : `<button class="btn btn--primary btn--sm" type="button">${I('upload')}Publish</button>`) : '';
        const menu = i === 0 ? `<div class="menu" role="menu" data-show="menu"><a href="admin-project-form.html" role="menuitem">${I('edit')}Edit project</a><button type="button" role="menuitem">${I('star')}${p.feat ? 'Remove from featured' : 'Feature'}</button><a href="project.html" role="menuitem">${I('ext')}View live page</a><div class="sep"></div><button type="button" class="danger" role="menuitem" disabled title="Projects with leads can't be deleted">${I('trash')}Delete (has ${p.leads} leads)</button></div>` : '';
        acts = `${main}<span class="menu-anchor"><button class="btn btn--ghost btn--sm btn--icon" type="button" aria-haspopup="menu" aria-label="More actions for ${p.n}">${I('more')}</button>${menu}</span>`;
      } else {
        acts = `<a class="btn btn--secondary btn--sm" href="builder-project-form.html">${I('edit')}Edit</a>${p.pub && p.mod === 'approved' ? `<a class="btn btn--ghost btn--sm" href="project.html">${I('ext')}View live</a>` : ''}`;
      }
      return `<tr><td class="main"><div class="cell"><div class="th">${FP.art(p.art[0], p.art[1])}</div><div><b>${p.n}</b><small>${p.l}${admin ? '' : ''}</small></div></div></td>${admin ? `<td data-label="Builder">${p.b}</td>` : ''}<td data-label="Price range" class="num">${p.p}</td><td data-label="Status"><div class="statusbar">${flags}</div></td><td class="acts-td"><div class="mod-actions">${acts}</div></td></tr>`;
    }).join('');
    return `<div class="phead"><div><h1>Projects</h1><p>${admin ? 'Review, moderate and manage every builder project.' : 'Your projects. Saving an edit sends the project for approval.'}</p></div><div class="actions"><a class="btn btn--primary" href="${admin ? 'admin-project-form.html' : 'builder-project-form.html'}">${I('plus')}Add project</a></div></div>
    ${admin ? '' : `<div class="alert alert--warning mb-4" role="note">${I('alert')}<div class="grow"><b>Edits go back for approval</b>When you save a change, the project is set to Pending and is hidden from the public site until it is approved again. <span class="flag">Confirm this rule</span></div></div>`}
    <div class="alert alert--danger mb-4" role="alert" data-show="delete-blocked">${I('alert')}<div class="grow"><b>This project can't be deleted</b>It has 128 leads. Unpublish it instead to take it off the public site.</div></div>
    <nav class="tabs ptabs" aria-label="Filter by status"><a class="tab on" href="#">All<span class="count">${admin ? 7 : 4}</span></a><a class="tab" href="#">Pending<span class="count${admin ? ' new' : ''}">${admin ? 3 : 1}</span></a><a class="tab" href="#">Approved<span class="count">${admin ? 3 : 2}</span></a><a class="tab" href="#">Rejected<span class="count">${admin ? 1 : 0}</span></a><a class="tab" href="#">Draft<span class="count">${admin ? 0 : 1}</span></a></nav>
    <div class="toolbar mb-4"><div class="search-input grow">${I('search')}<input class="input" type="search" placeholder="Search projects" aria-label="Search projects"></div>${admin ? '<select class="select" aria-label="Builder"><option>All builders</option><option>Kadal Homes</option><option>Nila Habitats</option></select>' : ''}</div>
    <div class="tbl-wrap" data-hide="empty"><div class="tbl-scroll"><table class="tbl tbl--stack"><thead><tr><th>Project</th>${admin ? '<th>Builder</th>' : ''}<th>Price range</th><th>Status</th><th class="r"><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows}</tbody></table></div><div class="tbl-foot"><span>${admin ? 6 : 4} projects</span></div></div>
    <div class="empty" data-show="empty" role="status"><h3>No projects yet</h3><p>${admin ? 'Projects created by builders will appear here for review.' : 'Add your first project. It is reviewed before it goes live.'}</p><a class="btn btn--primary" href="${admin ? 'admin-project-form.html' : 'builder-project-form.html'}">${I('plus')}Add project</a></div>
    <div style="position:fixed;left:50%;transform:translateX(-50%);bottom:24px;z-index:110;width:min(440px,calc(100% - 32px))" data-show="toast"><div class="toast toast--success" role="status">${I('check-circle')}<div class="grow"><b>${admin ? 'Nila Grove approved' : 'Changes sent for approval'}</b>${admin ? 'It is not public until you publish it.' : 'We will notify you here once it is reviewed.'}</div></div></div>
    <div class="scrim" data-show="confirm-reject" role="alertdialog" aria-modal="true" aria-labelledby="cr-t"><div class="dialog"><span class="icon-disc danger">${I('x-circle')}</span><h2 id="cr-t">Reject Nila Grove?</h2><p>The builder will see the project as Rejected and it stays off the public site. You can approve it later.</p><div class="actions"><button class="btn btn--secondary" type="button">Cancel</button><button class="btn btn--danger" type="button">Reject project</button></div></div></div>
    <div class="scrim" data-show="confirm-delete" role="alertdialog" aria-modal="true" aria-labelledby="cdp-t"><div class="dialog"><span class="icon-disc danger">${I('trash')}</span><h2 id="cdp-t">Delete Thendral Residency?</h2><p>This permanently deletes the project and its units. It has no leads, so it can be deleted. This can't be undone.</p><div class="actions"><button class="btn btn--secondary" type="button">Cancel</button><button class="btn btn--danger" type="button">${I('trash')}Delete project</button></div></div></div>`;
  };

  /* ── Units (P-16 admin, P-27 builder) ── */
  FP.unitsPage = function (mode) {
    const admin = mode === 'admin';
    const st = { available: 'badge--success', hold: 'badge--warning', sold: 'badge--neutral', blocked: 'badge--info' };
    const U = [['A-101', 1, 2, '1,050', 'East', '₹78 L', 'available'], ['A-102', 1, 3, '1,450', 'North', '₹1.12 Cr', 'hold'], ['A-201', 2, 2, '1,060', 'East', '₹80 L', 'sold'], ['A-202', 2, 3, '1,460', 'North', '₹1.14 Cr', 'available'], ['B-301', 3, 3, '1,480', 'West', '₹1.18 Cr', 'available'], ['B-302', 3, 2, '1,075', 'South', '₹84 L', 'blocked']];
    const rows = U.map((u) => `<tr><td class="main"><b>${u[0]}</b></td><td data-label="Floor">${u[1]}</td><td data-label="BHK">${u[2]}</td><td data-label="Area" class="num">${u[3]} sq.ft</td><td data-label="Facing">${u[4]}</td><td data-label="Price" class="num">${u[5]}</td><td data-label="Status"><span class="badge ${st[u[6]]} dot">${{ available: 'Available', hold: 'On hold', sold: 'Sold', blocked: 'Blocked' }[u[6]]}</span></td><td class="acts-td"><div class="acts"><button class="btn btn--ghost btn--sm" type="button">${I('edit')}Edit</button><button class="btn btn--ghost btn--sm" type="button" style="color:var(--c-danger)" aria-label="Delete unit ${u[0]}">${I('trash')}</button></div></td></tr>`).join('');
    return `<div class="phead"><div><h1>Units</h1><p>${admin ? 'Manage the units of any project.' : 'Manage the units in your projects.'}</p></div><div class="actions"><button class="btn btn--primary" type="button">${I('plus')}Add unit</button></div></div>
    <div class="toolbar mb-4"><div class="field" style="min-width:min(280px,100%)"><label class="label" for="u-proj">Project</label><select id="u-proj" class="select"><option>Kadal Vista</option><option>Kadal Courts</option></select></div>
      <div class="search-input grow" style="align-self:flex-end">${I('search')}<input class="input" type="search" placeholder="Search unit number" aria-label="Search units"></div>
      <div class="chip-row single" style="align-self:flex-end"><button class="chip chip--sm on" type="button">All</button><button class="chip chip--sm" type="button">Available</button><button class="chip chip--sm" type="button">On hold</button><button class="chip chip--sm" type="button">Sold</button></div></div>
    <div class="tbl-wrap" data-hide="empty"><div class="tbl-scroll"><table class="tbl tbl--stack"><thead><tr><th>Unit</th><th>Floor</th><th>BHK</th><th>Area</th><th>Facing</th><th class="r">Price</th><th>Status</th><th class="r"><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows}</tbody></table></div><div class="tbl-foot"><span>6 of 320 units</span><span class="small">Units can't be moved to another project.</span></div></div>
    <div class="empty" data-show="empty" role="status"><h3>No units in this project yet</h3><p>Add units so buyers can see what is available.</p><button class="btn btn--primary" type="button">${I('plus')}Add unit</button></div>
    <div class="scrim right" data-show="drawer" role="dialog" aria-modal="true" aria-labelledby="ud-t"><div class="drawer-side"><header><h2 class="h3" id="ud-t">Add unit</h2><button class="icon-btn" type="button" aria-label="Close">${I('x')}</button></header>
      <div class="body"><form class="form-grid two" novalidate>
        <div class="field span-2" data-show="errors"><label class="label" for="ud-n">Unit number<span class="req">*</span></label><input id="ud-n" class="input is-error" aria-invalid="true" aria-describedby="ud-ne"><div class="error" id="ud-ne">${I('alert')}Enter a unit number.</div></div>
        <div class="field span-2" data-hide="errors"><label class="label" for="ud-n2">Unit number<span class="req">*</span></label><input id="ud-n2" class="input" value="B-303"></div>
        <div class="field"><label class="label" for="ud-f">Floor</label><input id="ud-f" class="input" inputmode="numeric" value="3"></div><div class="field"><label class="label" for="ud-b">BHK</label><select id="ud-b" class="select"><option>2</option><option selected>3</option></select></div>
        <div class="field"><label class="label" for="ud-a">Area (sq.ft)</label><input id="ud-a" class="input" inputmode="numeric" value="1480"></div><div class="field"><label class="label" for="ud-fc">Facing</label><select id="ud-fc" class="select"><option>East</option><option>North</option><option selected>West</option><option>South</option></select></div>
        <div class="field"><label class="label" for="ud-p">Price (₹)</label><input id="ud-p" class="input" inputmode="numeric" value="11800000"></div><div class="field"><label class="label" for="ud-s">Status</label><select id="ud-s" class="select"><option selected>Available</option><option>On hold</option><option>Sold</option><option>Blocked</option></select></div>
        <div class="field"><label class="label" for="ud-d">Available from</label><div class="input-wrap"><input id="ud-d" class="input" value="1 Dec 2026">${I('calendar', 'end')}</div></div><div class="field"><label class="label" for="ud-u">Floor plan link <span class="opt">(optional)</span></label><input id="ud-u" class="input" placeholder="https://"></div>
      </form></div><footer><button class="btn btn--secondary" type="button">Cancel</button><button class="btn btn--primary" type="button">Save unit</button></footer></div></div>
    <div class="scrim" data-show="confirm-delete" role="alertdialog" aria-modal="true" aria-labelledby="udd-t"><div class="dialog"><span class="icon-disc danger">${I('trash')}</span><h2 id="udd-t">Delete unit B-302?</h2><p>This removes the unit from the project. This can't be undone.</p><div class="actions"><button class="btn btn--secondary" type="button">Cancel</button><button class="btn btn--danger" type="button">Delete unit</button></div></div></div>`;
  };

  /* ── Leads (P-18 admin, P-28 builder) ── */
  FP.leadsPage = function (mode) {
    const admin = mode === 'admin';
    const L = [['28 Oct, 10:42', 'Kadal Vista', 'enquiry', 'Arjun Menon', '98410 55512', 'arjun.menon@example.com', 'Is a 3 BHK on a high floor still available?', 'new'], ['28 Oct, 09:15', 'Arivu Heights', 'site_visit', 'Divya Krishnan', '98840 21098', '—', 'Saturday morning works.', 'contacted'], ['27 Oct, 18:03', 'Kadal Vista', 'brochure', 'Revathi P', '99401 88231', 'revathi.p@example.com', '—', 'closed'], ['27 Oct, 14:27', 'Nila Grove', 'enquiry', 'Suresh N', '97876 20144', 'suresh.n@example.com', 'Please share the payment plan.', 'new']];
    const kind = { enquiry: 'badge--info', site_visit: 'badge--featured', brochure: 'badge--neutral' };
    const rows = L.map((r) => `<tr><td data-label="Date" class="main nw"><b>${r[0]}</b></td><td data-label="Project" class="nw">${r[1]}</td><td data-label="Type"><span class="badge ${kind[r[2]]}">${r[2].replace('_', ' ')}</span></td><td data-label="Name" class="nw">${r[3]}</td><td data-label="Phone" class="nw"><a class="tl" href="tel:${r[4]}">${r[4]}</a></td><td data-label="Email" class="nw">${r[5]}</td><td data-label="Message"><span class="clamp-2" style="max-width:200px;display:-webkit-box">${r[6]}</span></td><td data-label="Status"><select class="select inline" aria-label="Status for ${r[3]}"><option${r[7] === 'new' ? ' selected' : ''}>New</option><option${r[7] === 'contacted' ? ' selected' : ''}>Contacted</option><option${r[7] === 'closed' ? ' selected' : ''}>Closed</option></select></td></tr>`).join('');
    const subs = [['28 Oct, 11:02', 'Priya Raman', '98400 12345', 'Kadal Vista', 'project_page', 'Enquiry form', 'Sales team', 'ok', 'CRM-4821'], ['28 Oct, 10:31', 'Anand V', '99620 11876', '—', 'contact_page', 'Contact', '—', 'failed', '—'], ['27 Oct, 20:44', 'Meena S', '98410 70011', 'Arivu Heights', 'project_page', 'Site visit', 'Sales team', 'ok', 'CRM-4817'], ['27 Oct, 16:10', 'Vikram R', '97101 30920', 'Nila Grove', 'project_page', 'Enquiry form', 'Sales team', 'queued', '—']];
    const crm = { ok: '<span class="badge badge--success dot">Delivered</span>', failed: '<span class="badge badge--danger dot">Failed</span>', queued: '<span class="badge badge--warning dot">Retrying</span>' };
    const srows = subs.map((r) => `<tr><td data-label="Created" class="main"><b>${r[0]}</b></td><td data-label="Name">${r[1]}</td><td data-label="Mobile">${r[2]}</td><td data-label="Project">${r[3]}</td><td data-label="Source">${r[4]}</td><td data-label="Form">${r[5]}</td><td data-label="Agent">${r[6]}</td><td data-label="CRM">${crm[r[7]]}${r[8] !== '—' ? `<small class="muted" style="display:block">${r[8]}</small>` : ''}</td></tr>`).join('');
    const proj = `<div class="tbl-wrap"><div class="tbl-scroll"><table class="tbl tbl--stack" style="min-width:980px"><thead><tr><th>Date</th><th>Project</th><th>Type</th><th>Name</th><th>Phone</th><th>Email</th><th>Message</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></div><div class="tbl-foot"><span>4 leads</span>${admin ? '' : '<span class="small">You can change a lead\'s status. Contact details can\'t be edited.</span>'}</div></div>`;
    const sub = `<div class="filter-card mb-4"><div class="field"><label class="label" for="s-d">Date range</label><select id="s-d" class="select"><option>Last 30 days</option></select></div><div class="field"><label class="label" for="s-f">Form</label><select id="s-f" class="select"><option>All forms</option></select></div><div class="field"><label class="label" for="s-p">Project</label><select id="s-p" class="select"><option>All projects</option></select></div><div class="field"><label class="label" for="s-s">Source</label><select id="s-s" class="select"><option>All sources</option></select></div><div class="field"><label class="label" for="s-c">CRM status</label><select id="s-c" class="select"><option>Any</option><option>Failed</option></select></div><div><button class="btn btn--secondary btn--block" type="button">Reset</button></div></div>
      <div class="tbl-wrap"><div class="tbl-scroll"><table class="tbl tbl--stack" style="min-width:980px"><thead><tr><th>Created</th><th>Name</th><th>Mobile</th><th>Project</th><th>Source</th><th>Form</th><th>Agent</th><th>CRM</th></tr></thead><tbody>${srows}</tbody></table></div><div class="tbl-foot"><span>4 submissions</span><span class="small">Select a row to see the full submission.</span></div></div>`;
    return `<div class="phead"><div><h1>Leads</h1><p>${admin ? 'Project leads and form submissions across the platform.' : 'Leads for your projects.'}</p></div></div>
    ${admin ? `<nav class="tabs ptabs" aria-label="Lead sources"><a class="tab" href="#project" data-tab="project">Project leads<span class="count">862</span></a><a class="tab" href="#submissions" data-tab="submissions">Form submissions<span class="count">1,104</span></a></nav>
      <div data-show="project">${proj}</div><div data-show="submissions">${sub}</div>` : proj}
    <div class="scrim right" data-show="detail" role="dialog" aria-modal="true" aria-labelledby="sd-t"><div class="drawer-side"><header><h2 class="h3" id="sd-t">Submission details</h2><button class="icon-btn" type="button" aria-label="Close">${I('x')}</button></header>
      <div class="body"><dl class="kv stack"><dt>Created</dt><dd>28 Oct 2026, 10:31</dd><dt>Name</dt><dd>Anand V</dd><dt>Mobile</dt><dd>99620 11876</dd><dt>Form</dt><dd>Contact</dd><dt>Message</dt><dd style="font-weight:500">I would like to speak about listing my plot in Medavakkam.</dd><dt>Files</dt><dd><a class="link" href="#">site-plan.pdf</a></dd></dl>
        <div class="alert alert--danger mt-4" role="alert">${I('alert')}<div class="grow"><b>CRM delivery failed</b>HTTP 502 on attempt 2. The next automatic retry is in 30 minutes.</div></div><button class="btn btn--primary mt-4" type="button">${I('refresh')}Retry delivery now</button></div></div></div>`;
  };

  /* ── Insights (P-25 dashboard compact, P-29 insights full) ── */
  FP.insightsPage = function (compact) {
    const S = FP.stat;
    const tiles = compact
      ? `<div class="kpi-group"><span class="overline">Portfolio</span><div class="stats c4">${S('Projects', '4', { icon: 'building' })}${S('Active projects', '3', { icon: 'check-circle', sub: 'Approved and published' })}${S('Total units', '520', { icon: 'layers' })}${S('Available units', '301', { icon: 'tag', sub: '164 sold' })}</div></div>
         <div class="kpi-group"><span class="overline">Activity this month</span><div class="stats c5">${S('Project views', '6,420', { icon: 'eye' })}${S('Unique visitors', '3,918', { icon: 'users' })}${S('Enquiries', '128', { icon: 'msg', tone: 'info' })}${S('Leads', '186', { icon: 'inbox', tone: 'copper' })}${S('Shortlists', '342', { icon: 'heart' })}</div></div>
         <div class="kpi-group"><span class="overline">Actions</span><div class="stats c5">${S('Comparisons', '97', { icon: 'cols' })}${S('Brochure downloads', '211', { icon: 'download' })}${S('Calls', '74', { icon: 'phone' })}${S('WhatsApp clicks', '63', { icon: 'msg' })}${S('Site visit requests', '29', { icon: 'calendar' })}</div></div>`
      : `<div class="kpi-group"><span class="overline">Activity</span><div class="stats c5">${S('Project views', '6,420', { icon: 'eye' })}${S('Unique visitors', '3,918', { icon: 'users' })}${S('Enquiries', '128', { icon: 'msg', tone: 'info' })}${S('Leads', '186', { icon: 'inbox', tone: 'copper' })}${S('Shortlists', '342', { icon: 'heart' })}</div>
         <div class="stats c5 mt-3">${S('Comparisons', '97', { icon: 'cols' })}${S('Brochure downloads', '211', { icon: 'download' })}${S('Calls', '74', { icon: 'phone' })}${S('WhatsApp clicks', '63', { icon: 'msg' })}${S('Site visit requests', '29', { icon: 'calendar' })}</div></div>`;
    const charts = compact ? '' : `<div class="dash-grid even"><section class="panel chart-card" aria-labelledby="i1"><div class="ch"><div><h2 id="i1">Views and visitors</h2><p>Per day, last 30 days</p></div></div><div id="ins-a"></div></section><section class="panel chart-card" aria-labelledby="i2"><div class="ch"><div><h2 id="i2">Leads and enquiries</h2><p>Per day, last 30 days</p></div></div><div id="ins-b"></div></section></div>
      <section class="panel chart-card" aria-labelledby="i3"><div class="ch"><div><h2 id="i3">Leads by project</h2><p>This period</p></div></div><div id="ins-c"></div></section>`;
    return `<div class="phead"><div><h1>${compact ? 'Dashboard' : 'Insights'}</h1><p>${compact ? 'A quick look at how your projects are doing.' : 'How visitors find and respond to your projects.'}</p></div></div>
      <div class="alert alert--warning mb-4" role="status" data-show="pending">${I('clock')}<div class="grow"><b>1 project is waiting for approval</b>Nila Grove was edited and is hidden from the public site until it is approved.</div></div>
      <div class="date-row"><div class="seg seg--sm" role="tablist" aria-label="Date range"><button type="button" role="tab">7 days</button><button type="button" role="tab" class="on">30 days</button><button type="button" role="tab">This month</button><button type="button" role="tab">Custom</button></div>${compact ? '' : `<select class="select" style="min-height:44px;width:auto;min-width:200px;border-radius:12px" aria-label="Project"><option>All projects</option><option>Kadal Vista</option><option>Kadal Courts</option></select>`}</div>
      <div id="ins-wrap">${tiles}${charts}</div>`;
  };
  FP.insightsCharts = function () {
    const days = Array.from({ length: 30 }, (_, i) => `${i + 1} Oct`);
    const wave = (b, a, ph, tr) => days.map((_, i) => Math.round(b + a * Math.sin(i / 3.4 + ph) + (tr * i) / 29));
    const q = (id) => document.getElementById(id);
    if (q('ins-a')) q('ins-a').innerHTML = FP.line({ title: 'Views and visitors per day', labels: days, series: [{ name: 'Views', slot: 1, data: wave(190, 40, 0.4, 60) }, { name: 'Visitors', slot: 4, data: wave(115, 28, 1.1, 40) }], yMax: 300, ticks: [0, 100, 200, 300], h: 260, tickEvery: 6 });
    if (q('ins-b')) q('ins-b').innerHTML = FP.line({ title: 'Leads and enquiries per day', labels: days, series: [{ name: 'Leads', slot: 2, data: wave(5, 2, 0, 2) }, { name: 'Enquiries', slot: 3, data: wave(3, 1.4, 1.5, 1) }], yMax: 10, ticks: [0, 5, 10], h: 260, tickEvery: 6 });
    if (q('ins-c')) q('ins-c').innerHTML = FP.hbars([['Kadal Vista', 128], ['Kadal Courts', 38], ['Kadal Bay', 20]], { title: 'Leads by project' });
    if (FP.renderCharts) FP.renderCharts(document.documentElement.dataset.tokens.split(' ').includes('hover') ? 18 : null);
  };

  T.projectspage = (a) => FP.projectsPage(a.mode);
  T.unitspage = (a) => FP.unitsPage(a.mode);
  T.leadspage = (a) => FP.leadsPage(a.mode);
  T.insightspage = (a) => FP.insightsPage(a.compact === '' || a.compact === 'true');
})();
